lessons.solution:
fn double_value(n: i32) -> i32 {
    n*2
}

fn absolute(n: i32) -> i32 {
    if n<0 {
        -n
    }
    else {
        n
    }
}

fn sum_to(n: u32) -> u32 {
    let mut total=0;
    for i in 1..=n {
        total+=i;
    }
    total
}

fn is_even(n: i32) -> bool {
    n%2==0
}

fn maximum(a: i32,b: i32) -> i32 {
    if a>b {
        a
    }
    else {
        b
    }
}

fn byte_length(s: &str) -> usize {
    s.len()
}

fn add_bang(s: &str) -> String {
    let mut out=s.to_owned();
    out.push('!');
    out
}

lessons.starter:
fn with_value(values: &[i32], x: i32) -> Vec<i32> {
    Vec::new()
}

lessons.solution:
fn with_value(values: &[i32], x: i32) -> Vec<i32> {
    let mut out=values.to_vec();
    out.push(x);
    out
}

fn sum_values(values: &[i32]) -> i32 {
    let mut total=0;
    for &n in values {
        total+=n;
    }
    total
}

fn replace_first(values: &[i32],x: i32) -> Vec<i32> {
    let mut out=values.to_vec();
    if let Some(first)=out.first_mut() {
        *first=x;
    }
    out
}

fn char_count(s: &str) -> usize {
    s.chars().count()
}

fn reverse_chars(s: &str) -> String {
    s.chars().rev().collect()
}

fn last_word(s: &str) -> &str {
    s.split_whitespace().last().unwrap_or("")
}

fn word_count(s: &str) -> usize {
    s.split_whitespace().count()
}

fn upper_ascii(s: &str) -> String {
    s.to_ascii_uppercase()
}

lessons.starter:
fn first_or(values: &[i32], fallback: i32) -> i32 {
    fallback
}

lessons.solution:
fn first_or(values: &[i32], fallback: i32) -> i32 {
    match values.first() {
        Some(x)=>*x,None=>fallback
    }
}

lessons.starter:
fn parse_or(s: &str, fallback: i32) -> i32 {
    fallback
}

lessons.solution:
fn parse_or(s: &str, fallback: i32) -> i32 {
    s.parse::<i32>().unwrap_or(fallback)
}

fn smallest(values: &[i32]) -> Option<i32> {
    values.iter().min().copied()
}

fn at(values: &[i32],index: usize) -> Option<i32> {
    values.get(index).copied()
}

lessons.starter:
fn safe_divide(n: i32,d: i32) -> Option<i32> {
    None
}

lessons.solution:
fn safe_divide(n: i32,d: i32) -> Option<i32> {
    if d==0 {
        None
    }
    else {
        Some(n/d)
    }
}

fn positive(values: &[i32]) -> Vec<i32> {
    values.iter().copied().filter(|n| *n>0).collect()
}

fn partial_sums(values: &[i32]) -> Vec<i32> {
    let mut total=0;
    let mut out=Vec::new();
    for &value in values {
        total+=value;
        out.push(total);
    }
    out
}

fn count_word(s: &str, wanted: &str) -> usize {
    let mut counts=std::collections::HashMap::new();
    for word in s.split_whitespace() {
        *counts.entry(word).or_insert(0usize)+=1;
    }
    counts.get(wanted).copied().unwrap_or(0)
}

fn sorted_copy(values: &[i32]) -> Vec<i32> {
    let mut out=values.to_vec();
    out.sort();
    out
}

fn unique(values: &[i32]) -> Vec<i32> {
    let mut seen=std::collections::HashSet::new();
    let mut out=Vec::new();
    for &n in values {
        if seen.insert(n) {
            out.push(n);
        }
    }
    out
}

fn is_prime(n: u32) -> bool {
    if n<2 {
        return false;
    }
    let mut d=2;
    while d<=n/d {
        if n%d==0 {
            return false;
        }
        d+=1;
    }
    true
}

fn fib(n: u32) -> u32 {
    let(mut a,mut b)=(0,1);
    for _ in 0..n {
        (a,b)=(b,a+b);
    }
    a
}

