lessons.solution:
enum Access {
    Read, Write
}
fn label(access: Access) -> &'static str {
    match access {
        Access::Read=>"read",Access::Write=>"write"
    }
}

fn balanced(s: &str) -> bool {
    let mut depth=0;
    for ch in s.chars() {
        if ch=='(' {
            depth+=1;
        }
        else {
            depth-=1;
        }
        if depth<0 {
            return false;
        }
    }
    depth==0
}

fn factorial(n: u32) -> u32 {
    if n<=1 {
        1
    }
    else {
        n*factorial(n-1)
    }
}
